        (
            f"({t.replace(_FUSED_NAME_SEP, ' ')})"
            if _FUSED_NAME_SEP in t and t not in fused_placeholders
            else t
        )
        for t in translated_order
    ]

    if source_tokens == target_tokens:
        return None

    return f"{' '.join(source_tokens)} -> {' '.join(target_tokens)}"


